const i={ui:{fig:"Fig. 3",title:"Recessed zipper",svgLabel:"An isometric drawing of how a recessed zipper is set in the top of a lined bag: four strips as long as the top edge of the bag, each zipper tape stitched between two of them, right sides inward, turned out and topstitched close to the teeth; the ends closed with fabric tabs; the panel sewn to the lining, middles matched. In the bag the zipper sits below the top edge, and the bag opens wide.",prev:"Previous step",dot:(e,t)=>e?`Step ${e}: ${t}`:t,start:"Steps →",next:"Next →",overview:"Overview",stepOf:(e,t)=>`Step ${e} of ${t}`,machine:e=>`Machine: ${e.toLowerCase()}`,inThisStep:"In this step",takeApart:"Open the zipper",putTogether:"Close the zipper",replay:"↻ Replay",parts:"Parts",allSteps:"Step-by-step instructions",endView:"END VIEW"},stitches:{straight:"Straight stitch"},labels:{fourStrips:"four strips",topLength:"as long as the top edge",zipperLonger:"zipper: a little longer",stripUp:"strip right side up",zipperDown:"zipper face down",stripDown:"second strip face down",alongEdge:"along the edge",turnOut:"turn out",pressAway:"press away from the teeth",nearTeeth:"close to the teeth",otherSide:"the other side, the same way",endsTabs:"ends: as in the second way",notOverStop:"not over the stop",toLining:"to the lining",middles:"middle on middle",asUsual:"then: outer and lining as usual",belowEdge:"below the edge",opensWide:"opens wide"},steps:[{title:"Recessed zipper at the top of a bag",text:"The zipper sits in a panel below the top edge of the bag, and the panel is sewn to the lining. Tap to open the zipper: the bag opens wide."},{title:"Four strips and a zipper",text:"Cut four strips as long as the top edge of the bag, two for each side of the zipper, and a zipper a little longer than the strips.",details:["Cut four strips of fabric as long as the top edge of the bag: two for each side of the zipper.","Patterns give different widths for the strips: the wider they are, the lower the zipper sits in the bag.","Many patterns iron interfacing onto the strips, so the panel keeps its shape.","Cut the zipper a little longer than the strips; a zipper by the yard can be cut to any length."]},{title:"Between two strips",text:"Lay a strip right side up, the zipper face down on it, edge to edge, and the second strip face down on top: right sides inward.",details:["Lay one strip right side up.","Lay the zipper face down on it, the edge of its tape on the long edge of the strip.","Lay the second strip face down on top, edges level: the zipper tape is now between two strips, right sides inward. Hold the layers with clips."]},{title:"Sew along the edge",text:"With the zipper foot, sew along the edge through the three layers: the strip, the zipper tape and the second strip.",details:["Put on the zipper foot: it lets you sew close to the teeth.","Sew along the long edge, through both strips and the zipper tape.","Keep the seam on the tape, beside the teeth, not over them."]},{title:"Turn out and press",text:"Turn the strips away from the zipper, wrong sides together, and press them away from the teeth.",details:["Fold the strips back from the zipper: the zipper now lies face up beside them.","The two strips lie wrong sides together, the seam hidden between them.","Press the strips away from the teeth, so the fabric stays out of the zipper."]},{title:"Topstitch close to the teeth",text:"With the zipper foot, topstitch along the strip close to the teeth, through both strips.",details:["With the zipper foot, topstitch along the edge of the strip by the zipper, close to the teeth.","The topstitching holds both strips flat and keeps the fabric away from the teeth."]},{title:"The other side",text:"Sew the other tape of the zipper between the two other strips the same way, with the zipper foot: sew, turn out, press and topstitch.",details:["Lay the two other strips right sides inward around the other zipper tape and sew along the edge with the zipper foot.","Turn them out, press them away from the teeth and topstitch close to the teeth.","The panel is ready: the zipper in the middle, two strips on each side."]},{title:"Close the ends",text:"Close both ends of the zipper with fabric tabs, as in the second way, Zipper with end tabs: stitched just past each stop, never over it.",details:["Make two fabric tabs and slip them over the ends of the zipper, as in the second way, Zipper with end tabs.","With the zipper foot, stitch each tab just past the stop, not over it: the stops are often metal, and the needle can break."]},{title:"To the lining",text:"Sew the panel to the lining, not to the outer: each long edge of the panel to the top edge of a lining piece, right sides together, middle on middle.",details:["Mark the middle of the panel's long edges and of the top edges of the lining pieces.","Lay one long edge of the panel on the top edge of a lining piece, right sides together, middle on middle, and hold them with clips.","Sew along the edge. Sew the other long edge to the other lining piece the same way.","The panel goes on the lining, not on the outer: so it ends up inside the bag, below the edge."]},{title:"The bag",text:"Then the outer and the lining are joined at the top edge as usual for a lined bag. The zipper sits below the edge, and the bag opens wide.",details:["Join the outer and the lining at the top edge as usual for a lined bag; the panel goes in with the lining.","The zipper sits below the top edge of the bag.","Opened, the panel drops against the sides, and the bag opens wide."]}],legend:[{title:"Panel",text:"four strips as long as the top edge of the bag · the zipper in the middle"},{title:"Zipper",text:"a little longer than the strips · its ends closed with tabs"},{title:"Lining",text:"the panel is sewn to it"},{title:"Outer",text:"joined to the lining as usual"}]};export{i as default};
